# 8x5 纵向镜像绕行地图；每个部署格均有一条绕行路线。
[map]
id=map_04
name=镜像绕行回廊
width=8
height=5
row_0=#A#..#B#
row_1=AA....BB
row_2=X#.##.#Y
row_3=AA....BB
row_4=#A#..#B#

# A 方上半区先向下进入中央，再经下方横道绕到 Y 守卫。
[route:a_top_edge]
side=A
start=1,0
points=1,0;1,1;2,1;2,2;2,3;3,3;4,3;5,3;5,2;5,1;6,1;7,1;7,2

[route:a_upper_outer]
side=A
start=0,1
points=0,1;1,1;2,1;2,2;2,3;3,3;4,3;5,3;5,2;5,1;6,1;7,1;7,2

[route:a_upper_inner]
side=A
start=1,1
points=1,1;2,1;2,2;2,3;3,3;4,3;5,3;5,2;5,1;6,1;7,1;7,2

# A 方下半区按手绘示例向上绕行，再从右下侧抵达 Y 守卫。
[route:a_lower_outer]
side=A
start=0,3
points=0,3;1,3;2,3;2,2;2,1;3,1;4,1;5,1;5,2;5,3;6,3;7,3;7,2

[route:a_lower_inner]
side=A
start=1,3
points=1,3;2,3;2,2;2,1;3,1;4,1;5,1;5,2;5,3;6,3;7,3;7,2

[route:a_bottom_edge]
side=A
start=1,4
points=1,4;1,3;2,3;2,2;2,1;3,1;4,1;5,1;5,2;5,3;6,3;7,3;7,2

# B 方路线是 A 方对应路线关于纵向中轴线的镜像。
[route:b_top_edge]
side=B
start=6,0
points=6,0;6,1;5,1;5,2;5,3;4,3;3,3;2,3;2,2;2,1;1,1;0,1;0,2

[route:b_upper_outer]
